            <p class="discovery-card__year">{{ game.releaseYear }}</p>
          }
        </div>
      </a>
    }
  </div>

  @if (hasMore()) {
    <button class="discovery__load-more" (click)="loadMore()" [disabled]="loadingMore()">
      {{ loadingMore() ? 'Loading...' : 'Load more' }}
    </button>
  }
}

