import { Component, inject, signal } from '@angular/core';
import { Router } from '@angular/router';
import { OnboardingService } from '../../../core/services/onboarding.service';
import { OnboardingPrefsStepComponent } from './onboarding-prefs-step/onboarding-prefs-step.component';
import { OnboardingSearchStepComponent } from './onboarding-search-step/onboarding-search-step.component';

@Component({
  selector: 'app-onboarding-page',
  imports: [OnboardingPrefsStepComponent, OnboardingSearchStepComponent],
  templateUrl: './onboarding-page.component.html',
  styleUrl: './onboarding-page.component.scss',
})
export class OnboardingPageComponent {
  private readonly onboardingService = inject(OnboardingService);
  private readonly router = inject(Router);

  step = signal<1 | 2>(1);
  selectedGenres = signal<string[]>([]);
  selectedPlatforms = signal<string[]>([]);
  submitting = signal(false);
  error = signal<string | null>(null);

  onPrefsComplete(data: { genres: string[]; platforms: string[] }) {
    this.selectedGenres.set(data.genres);
    this.selectedPlatforms.set(data.platforms);
    this.step.set(2);
  }

  onSearchComplete(seededGameIds: string[]) {
    this.submitting.set(true);
    this.error.set(null);
    this.onboardingService
      .complete({
        favouriteGenres: this.selectedGenres(),
        platforms: this.selectedPlatforms(),
        seededGameIds: seededGameIds.length ? seededGameIds : undefined,
      })
      .subscribe({
        next: () => this.router.navigateByUrl('/feed'),
        error: () => {
          this.error.set('Something went wrong. Please try again.');
          this.submitting.set(false);
        },
      });
  }

  onBack() {
    this.step.set(1);
  }
}

import { Component, EventEmitter, Output, signal } from '@angular/core';

const GENRES = [
  'Action', 'Adventure', 'RPG', 'Strategy', 'Simulation',
  'Sports', 'Racing', 'Fighting', 'Shooter', 'Puzzle',
  'Horror', 'Platform', 'Indie', 'MMORPG', 'Stealth',
];

const PLATFORMS = ['PC', 'PlayStation', 'Xbox', 'Switch', 'Mobile'];

@Component({
  selector: 'app-onboarding-prefs-step',
  templateUrl: './onboarding-prefs-step.component.html',
  styleUrl: './onboarding-prefs-step.component.scss',
})
export class OnboardingPrefsStepComponent {
  @Output() completed = new EventEmitter<{ genres: string[]; platforms: string[] }>();

  readonly genres = GENRES;
  readonly platforms = PLATFORMS;

  selectedGenres = signal<Set<string>>(new Set());
  selectedPlatforms = signal<Set<string>>(new Set());

  toggleGenre(genre: string) {
    const next = new Set(this.selectedGenres());
    next.has(genre) ? next.delete(genre) : next.add(genre);
    this.selectedGenres.set(next);
  }

  togglePlatform(platform: string) {
    const next = new Set(this.selectedPlatforms());
    next.has(platform) ? next.delete(platform) : next.add(platform);
    this.selectedPlatforms.set(next);
  }

  isGenreSelected(genre: string) {
    return this.selectedGenres().has(genre);
  }

  isPlatformSelected(platform: string) {
    return this.selectedPlatforms().has(platform);
  }

  canContinue() {
    return this.selectedGenres().size > 0 && this.selectedPlatforms().size > 0;
  }

  continue() {
    if (!this.canContinue()) return;
    this.completed.emit({
      genres: [...this.selectedGenres()],
      platforms: [...this.selectedPlatforms()],
    });
  }
}

import { Component, EventEmitter, Input, Output, signal } from '@angular/core';
import { GameSearchInputComponent } from '../../../../shared/components/game-search-input/game-search-input.component';
import { GameSummary } from '../../../../core/models/game.model';

@Component({
  selector: 'app-onboarding-search-step',
  imports: [GameSearchInputComponent],
  templateUrl: './onboarding-search-step.component.html',
  styleUrl: './onboarding-search-step.component.scss',
})
export class OnboardingSearchStepComponent {
  @Input() submitting = false;
  @Input() error: string | null = null;
  @Output() completed = new EventEmitter<string[]>();
  @Output() back = new EventEmitter<void>();

  seededGames = signal<GameSummary[]>([]);

  onGameSelected(game: GameSummary) {
    if (this.seededGames().some(g => g.id === game.id)) return;
    this.seededGames.update(list => [...list, game]);
  }

  removeGame(id: string) {
    this.seededGames.update(list => list.filter(g => g.id !== id));
  }

  coverUrl(game: GameSummary): string | null {
    if (!game.coverImageId) return null;
    return `https://images.igdb.com/igdb/image/upload/t_thumb/${game.coverImageId}.jpg`;
  }

  finish() {
    this.completed.emit(this.seededGames().map(g => g.id));
  }
}

import { Component, Input, Output, EventEmitter, signal } from '@angular/core';
import { PLATFORM_LABELS } from '../../../core/utils/platform-labels';

@Component({
  selector: 'app-owned-toggle',
  imports: [],
  templateUrl: './owned-toggle.component.html',
  styleUrl: './owned-toggle.component.scss'
})
export class OwnedToggleComponent {
  @Input() isOwned = false;
  @Input() ownedPlatforms: string[] = [];
  @Input() availablePlatforms: string[] = [];
  @Output() ownedChange = new EventEmitter<{ isOwned: boolean; platforms: string[] }>();

  showPicker = signal(false);
  selected = signal<string[]>([]);

  label(platform: string): string {
    return PLATFORM_LABELS[platform] ?? platform;
  }

  get platformsLabel(): string {
    if (!this.ownedPlatforms.length) return '';
    const names = this.ownedPlatforms.map(p => this.label(p));
    if (names.length <= 2) return names.join(', ');
    return `${names.slice(0, 2).join(', ')} +${names.length - 2}`;
  }

  open() {
    this.selected.set([...this.ownedPlatforms]);
    this.showPicker.set(true);
  }

  close() {
    this.showPicker.set(false);
  }

  togglePlatform(platform: string) {
    const cur = this.selected();
    this.selected.set(
      cur.includes(platform) ? cur.filter(p => p !== platform) : [...cur, platform]
    );
  }

  save() {
    this.ownedChange.emit({ isOwned: true, platforms: this.selected() });
    this.showPicker.set(false);
  }

  unmark() {
    this.ownedChange.emit({ isOwned: false, platforms: [] });
    this.showPicker.set(false);
  }
}

