src/app/core/guards/auth.guard.ts.defaultValue:
(route, state) => {
  const authService = inject(AuthService);
  const router = inject(Router);

  return toObservable(authService.initialized).pipe(
    filter((initialized) => initialized === true),
    take(1),
    map(() => {
      if (!authService.isAuthenticated()) {
        return router.createUrlTree(['/login'], {
          queryParams: { returnUrl: state.url },
        });
      }
      return true;
    }),
  );
}

src/app/core/interceptors/error.intercep.defaultValue:
(req, next) => {
  const authService = inject(AuthService);
  return next(req).pipe(
    catchError(error => {
      if (error.status === 401 && !req.url.includes('/auth/')) {
        return authService.refreshSession().pipe(
          switchMap(() => next(req)),  
          catchError(_refreshError => {
            authService.logout();
            return throwError(() => error);
          })
        );
      }
      return throwError(() => error);
    })
  );
}

src/app/core/guards/guest.guard.ts.defaultValue:
(_route, _state) => {
  const authService = inject(AuthService);
  const router = inject(Router);

  return toObservable(authService.initialized).pipe(
    filter(initialized => initialized === true),
    take(1),
    map(() => {
      if (authService.isAuthenticated()) {
        return router.parseUrl('/feed');
      }
      return true
    })
  );
}

src/app/core/interceptors/jwt.intercepto.defaultValue:
(req, next) => {
  const authService = inject(AuthService);
  const token = authService.getToken();

  if (token) {
    req = req.clone({
      withCredentials:true,
      setHeaders: {
        Authorization: `Bearer ${token}`
      }
    });
  }

  return next(req);
}

